import { useEffect, useState } from "react";
import { Link, useNavigate, useLocation } from "react-router-dom";
import {
  Box,
  Typography,
  TextField,
  Button,
  Card,
  CardContent,
  MenuItem,
  Modal,
  CircularProgress,
} from "@mui/material";
import { supabase } from "../supabase";

const SignUpPage = () => {
  const [name, setName] = useState("");
  const [dob, setDob] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [role, setRole] = useState("student");
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [verificationStatus, setVerificationStatus] = useState("waiting");

  const navigate = useNavigate();
  const location = useLocation();

  const handleSignUp = async (e) => {
    e.preventDefault();
    setError(null);

    if (!name || !dob || !email || !password || !role) {
      setError("All fields are required!");
      return;
    }

    setLoading(true);
    try {
      const { error: signUpError } = await supabase.auth.signUp({
        email,
        password,
        options: {
          emailRedirectTo: `${window.location.origin}/verify`, // ✅ fixed here
          data: { name, dob, role },
        },
      });

      if (signUpError) throw signUpError;

      setShowModal(true);
      setVerificationStatus("waiting");
    } catch (err) {
      setError(err.message);
    }
    setLoading(false);
  };

  const handleCloseModal = () => {
    setShowModal(false);
    navigate("/signin");
  };

  return (
    <>
      <Box sx={{ width: "100vw", height: "100vh", display: "flex", overflow: "hidden" }}>
        {/* Left Section */}
        <Box
          sx={{
            width: "50%",
            backgroundColor: "#8E2839",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "center",
            color: "white",
            padding: "40px",
            position: "relative",
            "&::before": {
              content: '""',
              position: "absolute",
              top: 0,
              right: "-50px",
              width: "100px",
              height: "100%",
              backgroundColor: "#FFF",
              borderRadius: "50%",
            },
          }}
        >
          <Typography variant="h4" fontWeight="bold" mb={2}>
            Welcome Back!
          </Typography>
          <Typography textAlign="center" mb={4} fontSize="1.125rem">
            To keep connected with us, please login with your personal info
          </Typography>
          <Link to="/signin">
            <Button
              variant="outlined"
              sx={{
                color: "white",
                borderColor: "white",
                padding: "10px 32px",
                borderRadius: "999px",
                fontSize: "1rem",
                transition: "0.3s",
                "&:hover": {
                  backgroundColor: "white",
                  color: "#8E2839",
                },
              }}
            >
              SIGN IN
            </Button>
          </Link>
        </Box>

        {/* Right Section */}
        <Box
          sx={{
            width: "50%",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "center",
            backgroundColor: "#FFF",
          }}
        >
          <Card sx={{ width: "90%", maxWidth: 420, padding: 3, boxShadow: 3, borderRadius: 3 }}>
            <CardContent>
              <Typography variant="h4" fontWeight="bold" color="#8E2839" mb={1}>
                Create Account
              </Typography>
              <Typography color="gray" mb={3}>
                Sign up to enjoy the feature of EXAM
              </Typography>

              <form onSubmit={handleSignUp}>
                <TextField fullWidth label="Full Name" value={name} onChange={(e) => setName(e.target.value)} required disabled={showModal} sx={{ mb: 2 }} />
                <TextField fullWidth type="date" label="Date of Birth" value={dob} onChange={(e) => setDob(e.target.value)} InputLabelProps={{ shrink: true }} required disabled={showModal} sx={{ mb: 2 }} />
                <TextField fullWidth label="Email" value={email} onChange={(e) => setEmail(e.target.value)} required disabled={showModal} sx={{ mb: 2 }} />
                <TextField fullWidth label="Password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} required disabled={showModal} sx={{ mb: 2 }} />
                <TextField select fullWidth label="Are you a Student or Professor?" value={role} onChange={(e) => setRole(e.target.value)} required disabled={showModal} sx={{ mb: 2 }}>
                  <MenuItem value="student">Student</MenuItem>
                  <MenuItem value="professor">Professor</MenuItem>
                </TextField>

                {error && (
                  <Typography color="red" fontSize="0.875rem" mb={2}>
                    {error}
                  </Typography>
                )}

                {!showModal && (
                  <Button
                    type="submit"
                    fullWidth
                    disabled={loading}
                    sx={{
                      backgroundColor: loading ? "#aaa" : "#8E2839",
                      color: "white",
                      padding: "12px",
                      borderRadius: "999px",
                      fontSize: "1.125rem",
                    }}
                  >
                    {loading ? "Creating Account..." : "Create Account"}
                  </Button>
                )}
              </form>
            </CardContent>
          </Card>
        </Box>
      </Box>

      {/* ✅ Verification Modal */}
      <Modal open={showModal} onClose={() => {}}>
        <Box
          sx={{
            position: "absolute",
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            width: 360,
            bgcolor: "background.paper",
            borderRadius: 2,
            boxShadow: 24,
            p: 4,
            textAlign: "center",
          }}
        >
          {verificationStatus === "waiting" && (
            <>
              <Typography variant="h6" mb={2} color="#8E2839">
                🎉 You're Almost There!
              </Typography>
              <Typography fontSize="0.95rem" mb={3}>
                We’ve sent you a confirmation link. Please verify your email to activate your account.
              </Typography>
            </>
          )}
        </Box>
      </Modal>
    </>
  );
};

export default SignUpPage;
